class Solution {
public:
    int minLength(string s) {
        int w = 0;
        for (int r = 0; r < (int)s.size(); r++) {
            if (w > 0 && ((s[w-1] == 'A' && s[r] == 'B') || (s[w-1] == 'C' && s[r] == 'D'))) {
                w--;
            } else {
                s[w] = s[r];
                w++;
            }
        }
        return w;
    }
};
